css:
.aha-footer{
  container:aha-footer / inline-size;
  font-family:var(--aha-font-product);
  background:var(--aha-white);
  border-top:1px solid var(--aha-border-strong);
}
.aha-footer *{box-sizing:border-box}
:where(.aha-footer) p,:where(.aha-footer) ul{margin:0;padding:0}
:where(.aha-footer) ul{list-style:none}
.aha-footer__inner{
  display:flex;flex-direction:column;align-items:stretch;
  max-width:calc(1280px + 2 * var(--aha-space-32));
  margin:0 auto;
  padding:var(--aha-section-space-block) var(--aha-space-32) 0;
}
.aha-footer__brand{display:block;width:fit-content;border-radius:var(--aha-radius-xs);text-decoration:none}
.aha-footer__columns{
  display:grid;grid-template-columns:repeat(5,minmax(0,1fr));align-items:start;
  gap:var(--aha-space-16) var(--aha-space-32);
  margin-top:var(--aha-section-space-group);
}
.aha-footer__column{display:flex;flex-direction:column;align-items:flex-start}
.aha-footer__heading{
  display:block;margin:0 0 var(--aha-space-16);
  font-size:var(--aha-size-l);font-weight:var(--aha-weight-regular);line-height:var(--aha-size-l);
  color:var(--aha-gray-80);text-decoration:none;
  transition:color var(--aha-motion-slow);
}
a.aha-footer__heading:hover{color:var(--aha-color-primary)}
.aha-footer__visually-hidden{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.aha-footer__link{
  display:block;padding:var(--aha-space-8) 0;
  font-size:var(--aha-size-default);font-weight:var(--aha-weight-regular);line-height:var(--aha-space-24);
  color:var(--aha-gray-80);text-decoration:none;
  transition:color var(--aha-motion-slow);
}
.aha-footer__link:hover{color:var(--aha-color-primary)}
.aha-footer__brand:focus-visible,.aha-footer__heading:focus-visible,.aha-footer__link:focus-visible{
  outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2);border-radius:var(--aha-radius-xs)
}

.aha-footer__band{margin-top:var(--aha-section-space-group);padding:var(--aha-space-32);background:var(--aha-bg-hover)}
.aha-footer__band-inner{
  display:flex;align-items:flex-start;justify-content:space-between;
  max-width:1280px;margin:0 auto;
}
.aha-footer__awards{display:flex;gap:var(--aha-space-12)}
.aha-footer__award{display:block;width:100%;max-width:80px;border-radius:var(--aha-radius-xs)}
.aha-footer__award img{display:block;width:100%;height:auto}
.aha-footer__award--wide img{width:110%;max-width:none}
.aha-footer__meta{display:flex;flex-direction:column;align-items:flex-end;gap:var(--aha-space-16)}
.aha-footer__social{display:grid;grid-auto-flow:column;grid-auto-columns:var(--aha-space-24);gap:0 var(--aha-space-16)}
.aha-footer__social-link{display:block;width:var(--aha-space-24);height:var(--aha-space-24);color:var(--aha-icon-muted);border-radius:var(--aha-radius-xs)}
.aha-footer__social-link img{display:block;width:100%;height:100%}
.aha-footer__social-link:focus-visible,.aha-footer__dmca:focus-visible,.aha-footer__award:focus-visible{outline:var(--aha-space-2) solid var(--aha-focus);outline-offset:var(--aha-space-2)}
.aha-footer__legal{display:flex;align-items:center;gap:0 var(--aha-space-16)}
.aha-footer__dmca{display:block;border-radius:var(--aha-radius-xs)}
.aha-footer__dmca img{display:block;width:150px;height:30px}
.aha-footer__copyright{display:flex;justify-content:center;padding:var(--aha-section-space-group) var(--aha-space-32) var(--aha-section-space-block);background:var(--aha-white)}
.aha-footer__copyright p{font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);line-height:1.5;color:var(--aha-gray-80)}
@container aha-footer (max-width:1439px){
  .aha-footer__heading{font-size:var(--aha-size-default);line-height:var(--aha-size-default);color:var(--aha-text-default)}
}
@container aha-footer (max-width:991px){
  .aha-footer__columns{grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--aha-space-48) var(--aha-space-32)}
  .aha-footer__column--features{grid-column:1;grid-row:1 / 3}
  .aha-footer__column--resources{grid-column:2;grid-row:1}
  .aha-footer__column--pricing{grid-column:3;grid-row:1}
}
@container aha-footer (max-width:991px){
  .aha-footer__band{padding:var(--aha-space-32) var(--aha-space-16)}
  .aha-footer__social{margin-bottom:var(--aha-space-16)}
  .aha-footer__copyright{padding-inline:var(--aha-space-16)}
}
@container aha-footer (max-width:767px){
  .aha-footer__inner,.aha-footer__band,.aha-footer__copyright{--aha-web-gutter:var(--aha-space-24);padding-inline:var(--aha-web-gutter)}
  .aha-footer__band-inner{flex-direction:column;align-items:center}
  .aha-footer__award{aspect-ratio:80 / 81}
  .aha-footer__award img{height:100%;object-fit:contain}
  .aha-footer__award--wide img{width:110%;height:100%}
  .aha-footer__legal{margin-bottom:var(--aha-space-16)}
  .aha-footer__dmca img{width:140px;height:28px}
  .aha-footer__columns{gap:var(--aha-space-32)}
}
@container aha-footer (max-width:479px){
  .aha-footer__inner,.aha-footer__band,.aha-footer__copyright{--aha-web-gutter:var(--aha-space-16);}
  .aha-footer__band-inner{gap:var(--aha-space-16)}
  .aha-footer__meta{align-items:center}
  .aha-footer__social{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--aha-space-12)}
  .aha-footer__legal{flex-wrap:wrap;justify-content:center}
  .aha-footer__columns{grid-template-columns:repeat(2,minmax(0,1fr))}
  .aha-footer__column--features{grid-column:auto;grid-row:span 2}
  .aha-footer__column--resources{grid-column:auto;grid-row:auto}
  .aha-footer__column--integrations{grid-column:2;grid-row:1}
  .aha-footer__column--pricing{grid-column:2;grid-row:2}
}
@container aha-footer (max-width:479px){
  .aha-footer__brand aha-product-lockup{zoom:.75}
}
